import { useEffect, useState } from 'react'
import { createPortal } from 'react-dom'
import { BottomActionContainerStyle, Error, Grid, Row } from '../../../../commonStyle/index.style'
import { SELECTION_ARROW } from '../../../../images'
import { LANG_STRINGS } from '../../../../lang'
import BottomActionSheet from '../../../BottomActionSheet'
import Button from '../../../Button'
import CustomCheckbox from '../../../CustomCheckbox'
import FormItemLabel from '../FormItemLabel'
import { MultipleSelectListStyle, MultipleSelectStyle, SearchInputStyle } from './index.style'

export const MultipleSelect = ({
  title, required, data, name, displayKey = 'title', dataKey = 'value',
  onRenderListItem = null, defaultValue = [], error, showChips = false,
  onChange = () => {}, checkboxColor, checkboxBgColor
}, parentRef) => {
  const [show, setShow] = useState(false)
  const [displayValue, setDisplayValue] = useState('')
  const [selectedItems, setSelectedItems] = useState(defaultValue)
  const [searchData, setSearchData] = useState(data)
  const [searchQuery, setSearchQuery] = useState('')
  const handleCloseSheet = () => setShow(false)
  const handleCheckboxChange = (e, value) => {
    const selected = [...selectedItems]
    const itemIndex = selected.indexOf(value)
    let newSelected = selected
    if (itemIndex === -1) {
      newSelected = [...selected, value]
    } else {
      newSelected = [...selected.slice(0, itemIndex), ...selected.slice(itemIndex + 1)]
    }
    onChange({
      name,
      value: newSelected
    })
    setDisplayValue(newSelected.length ? `${newSelected.length} terpilih` : '')
    setSelectedItems(newSelected)
  }
  const handleSearch = (e) => {
    setSearchQuery(e.target.value)
  }

  useEffect(() => {
    if (searchQuery) {
      const lowSearch = searchQuery.toLowerCase()
      setSearchData(data.filter(x => {
        const res = `${x[dataKey]}`.toLowerCase()
          .includes(lowSearch) ||
          `${x[displayKey]}`.toLowerCase().includes(lowSearch)
        return res
      }))
    } else {
      setSearchData([...data])
    }
  }, [searchQuery, data, setSearchData, displayKey, dataKey])
  return (
    <MultipleSelectStyle>
      <FormItemLabel
        title={title}
        required={required}
      />
      <div className='auto-input-box'>
        <Grid
          gridColumn='1fr 14px'
          gridGap='0.9rem'
          onClick={() => setShow(true)}
          className='auto-search-input'
        >
          <div className='autocomplete-text'>
            {displayValue || LANG_STRINGS.select}
          </div>
          <div>
            <img src={SELECTION_ARROW} alt='' />
          </div>
        </Grid>
        {
          error && <Error>{error}</Error>
        }
      </div>
      {
        showChips && (
          <div className='selected-chips'>
            {
              selectedItems.map(optionValue => (
                <div key={optionValue} className='selected-chip'>{data.filter(dataItem => dataItem[dataKey] === optionValue)[0][displayKey]}</div>
              ))
            }
          </div>
        )
      }
      {
        show && createPortal(
          <BottomActionSheet
            show={show}
            zIndex={3}
            showHeader
            title={
              <SearchInputStyle>
                <input
                  className='search-input'
                  placeholder={`${LANG_STRINGS.search}...`}
                  onChange={handleSearch}
                  value={searchQuery}
                />
              </SearchInputStyle>
            }
            modalClose={false}
            onCloseSheet={() => setSearchQuery('')}
            className='multiple-select-sheet'
          >
            <MultipleSelectListStyle>
              <div className='btn-clear-selected'>
                <span
                  onClick={() => {
                    setDisplayValue('')
                    setSelectedItems([])
                    onChange({
                      name,
                      value: []
                    })
                  }}
                >
                  {LANG_STRINGS.clearSelections}
                </span>
              </div>
              {searchData?.map(option => (
                <div key={option[dataKey]} className='multiple-select-option'>
                  <CustomCheckbox
                    onChange={handleCheckboxChange}
                    name={option[dataKey]}
                    isChecked={selectedItems.includes(option[dataKey])}
                    checkboxBgColor={checkboxBgColor}
                    checkboxColor={checkboxColor}
                  />
                  {
                    onRenderListItem ? onRenderListItem(option) : option[displayKey]
                  }
                </div>
              ))}
              <div className='multiple-select-padding-btm' />
            </MultipleSelectListStyle>
            <BottomActionContainerStyle padding='0'>
              <Row className='button-wrapper'>
                <Button handleClick={handleCloseSheet}>{LANG_STRINGS.saveNew}</Button>
              </Row>
            </BottomActionContainerStyle>
          </BottomActionSheet>,
          document.getElementById('bottom-sheet-portal')
        )
      }
    </MultipleSelectStyle>
  )
}

export default MultipleSelect
