import BottomActionSheet from '../../../../../components/BottomActionSheet'
import { LANG_STRINGS } from '../../../../../lang/index'
import { PkgListFilterChip, PkgListFilterStyle } from './index.style'
import Heading from '../../../../../components/Heading/index'
import { PKG_LIST_SORT_FILTER } from '../../constants'
import { Grid } from '../../../../../commonStyle/index.style'
import { useState, useCallback, useRef, useMemo } from 'react'
import { Button, CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import Switch from '../../../../../components/Switch/index'
import PolicyAddons from '../../../../../components/PolicyAddons'
import { get } from 'lodash/object'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import DotLoader from '../../../../../components/DotLoader/index'

function PkgListFilterBottomSheet ({
  show, onClose, onSubmit = () => {}, pageData,
  activeFiltersData = {}
}) {
  const [activeFilter, setActiveFilter] = useState(activeFiltersData.sort || pageData.applicationData.sort)
  const [showAddons, setShowAddons] = useState(activeFiltersData.isShowAddons || false)
  const [{ GET_ALL_ADDONS_LOADER }] = useLoaderContextValue()
  const that = useRef(activeFiltersData.addonsData || {})

  const addonsData = useMemo(() => {
    const { applicationData = {} } = pageData
    return {
      data: {
        purchase_type: get(applicationData, 'purchase_type', ''),
        package_type: get(applicationData, 'package_type', ''),
        vehicle_type: get(applicationData, 'vehicle_type', ''),
        brand: get(applicationData, 'brand', ''),
        variant: get(applicationData, 'variant', ''),
        variant_code: get(applicationData, 'variant_code', ''),
        additional_sum_insured: get(applicationData, 'additional_sum_insured', ''),
        year: get(applicationData, 'year', ''),
        model: get(applicationData, 'model', ''),
        region_code: get(applicationData, 'region_code', ''),
        vehicle_sum_insured: get(applicationData, 'vehicle_sum_insured', ''),
        vehicle_plate_no: get(applicationData, 'vehicle_plate_no', ''),
        usage: get(applicationData, 'usage', ''),
        start_date: get(applicationData, 'start_date', ''),
        accessories: get(applicationData, 'accessories', '')
      },
      policyDetail: {
        ...applicationData
      },
      addons: get(applicationData, 'addons_data.add_ons', []),
      addonsCategory: applicationData?.add_ons_cat
    }
  }, [pageData])

  const handleActiveFilter = useCallback((filter) => {
    setActiveFilter(filter)
  }, [])

  const handleSubmit = useCallback(() => {
    onSubmit({
      sort: activeFilter,
      addonsData: that.current,
      isShowAddons: showAddons
    })
  }, [activeFilter, onSubmit, showAddons])

  const handleSwitch = useCallback(() => {
    // setShowAddons(prevShowAddons => {
    //   if (prevShowAddons) {
    //     that.current = {}
    //   }
    //   return !prevShowAddons
    // })
    // setShowAddonsModal(true)
  }, [])

  const handleChangesInAddon = useCallback((addonData) => {
    // save the addon data on that ref
    that.current = addonData
  }, [])

  return (
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      title={LANG_STRINGS.exitInFilter}
      showHeader
    >
      <PkgListFilterStyle>
        <Heading
          title={LANG_STRINGS.sortSearchResult}
          size='0.8em'
        />
        <Grid gridColumn='1fr 1fr 1fr 1fr' gridGap='0.7rem'>
          {
            PKG_LIST_SORT_FILTER.map((filter) => (
              <PkgListFilterChip
                key={filter.value}
                active={filter.value === activeFilter}
                onClick={() => handleActiveFilter(filter.value)}
              >
                {filter.name}
              </PkgListFilterChip>
            ))
          }
        </Grid>
        <div className='filter-addons-sections'>
          <Grid gridColumn='9fr 1fr' gridGap='0.7rem'>
            <Heading
              title={LANG_STRINGS.sortSearchResult}
              size='0.8em'
            />
            <CustomText
              size='0.6em'
              color={AgentColorPallette.fontGrey}
            >
              {LANG_STRINGS.optional}
            </CustomText>
          </Grid>
          <Grid
            gridColumn='5fr 1fr'
            gap='1rem'
            align='center'
          >
            <CustomText
              color={AgentColorPallette.blackGrey}
              size='0.8rem'
            >
              {LANG_STRINGS.selectOptionIfYouWantAdditionalCoverage}
            </CustomText>
            <Switch
              onChange={handleSwitch}
              id='addons'
              isChecked={showAddons}
              className='justify-self-end'
            />
          </Grid>
          <CustomText
            color={AgentColorPallette.regular}
            size='0.8rem'
            weight={700}
            top='4px'
            bottom='1rem'
          >
            {LANG_STRINGS.additionalFeesApply}
          </CustomText>
          {
            showAddons && (
              <PolicyAddons
                productId='car-protection'
                isProductAddons
                data={addonsData}
                onChangeAddon={handleChangesInAddon}
                isMVProduct
                isAddonV2
                preFilledAddons={addonsData.addonsCategory ? null : (that.current)}
              />
            )
          }
          {
            GET_ALL_ADDONS_LOADER && (
              <div className='circular-loader'>
                <DotLoader />
              </div>
            )
          }
        </div>
        <Button
          onClick={handleSubmit}
          disabled={!activeFilter}
          backgroundColor={AgentColorPallette.fontLightGrey}
          className='btn-border'
        >
          {LANG_STRINGS.save}
        </Button>
      </PkgListFilterStyle>
    </BottomActionSheet>
  )
}

export default PkgListFilterBottomSheet
