import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'

export const PolicyAddonsContext = createContext()

export const PolicyAddonsContextProvider = (props) => {
  return (
    <PolicyAddonsContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </PolicyAddonsContext.Provider>
  )
}

export const usePolicyAddonsContextValue = () => useContext(PolicyAddonsContext)
