import { useCallback, useMemo, useRef, useState } from 'react'
import { Select } from '../../..'
import { Row } from '../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import {
  ADDONS_THIRD_PARTY_AMOUNT_RANGE_WITH_MAX,
  DRIVER_PASS_DATA_CODE,
} from '../../../../containers/Private/Application/constants'
import { formatMoney } from '../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../lang'
import CustomCheckbox from '../../../CustomCheckbox'
import CustomText from '../../../CustomText'
import QuantityAddRemove from '../../../QuantityAddRemove'
import { AddonItemStyle } from './index.style'

function AddonItem(props) {
  const {
    item = {},
    selectedItem = {},
    onSelectItem,
    onPremiumCalculation,
    hidePremium = false,
    currencyType,
  } = props
  const data = ADDONS_THIRD_PARTY_AMOUNT_RANGE_WITH_MAX(
    item.max_sum_insured,
    currencyType
  )
  const isQTYAddon = useMemo(
    () => item.add_on_code === 'passenger-insurance',
    [item.add_on_code]
  )
  const that = useRef({})
  const [checked, setChecked] = useState(
    selectedItem.add_on_code === item.add_on_code
  )
  const [state, setState] = useState({
    isQTYAddon,
  })
  const [selectedPremium, setSelectedPremium] = useState()
  const [qty, setQty] = useState(selectedItem.no_passanger || 1)

  const getPremium = useCallback(
    (value) => {
      that.current.initialPremium = value ? value * item.percentage : 0
      if (hidePremium) {
        that.current.initialPremium = value
      }
      return that.current.initialPremium
    },
    [item, hidePremium]
  )

  const defaultData = useMemo(() => {
    const { show_drop_down: showPremiumDropDown, premium } = item
    let defaultSelect = showPremiumDropDown ? 15000000 : 0
    let addedPremium = selectedItem.premium || premium || state.premium
    if (DRIVER_PASS_DATA_CODE.includes(item.add_on_code)) {
      // data = ADDONS_PASSENGER_LIMIT
      defaultSelect = 25000000
    }

    if (!premium && addedPremium) {
      // there must be selected value for this case from select
      defaultSelect = selectedItem.limit || defaultSelect
    } else if (!premium && showPremiumDropDown) {
      addedPremium = getPremium(defaultSelect)
    }

    if (item.max_sum_insured && defaultSelect > item.max_sum_insured) {
      defaultSelect = item.max_sum_insured
    }

    if (qty) {
      addedPremium = addedPremium * qty
    }
    return {
      defaultSelect,
      addedPremium,
    }
  }, [item, selectedItem, getPremium, state, qty])

  const addRemoveAddon = useCallback(
    ({ limit = 0, actionType, qtyCount = qty }) => {
      onSelectItem(
        {
          ...item,
          limit,
          premium:
            selectedItem.premium ||
            item.premium ||
            state.premium ||
            that.current.initialPremium ||
            0,
          no_passanger: qtyCount,
        },
        actionType
      )
    },
    [onSelectItem, item, state.premium, qty, selectedItem.premium]
  )

  const handleChangeCheckbox = useCallback(
    (item) => {
      setChecked((checked) => {
        addRemoveAddon({
          actionType: !checked ? 'add' : 'remove',
          limit: selectedPremium || defaultData.defaultSelect,
        })
        if (!checked && !hidePremium && item.calc_method === 'p_calc') {
          onPremiumCalculation({
            ...item,
            limit: selectedPremium || defaultData.defaultSelect,
            value: selectedPremium || defaultData.defaultSelect,
          })
        }
        return !checked
      })
    },
    [
      addRemoveAddon,
      onPremiumCalculation,
      selectedPremium,
      defaultData.defaultSelect,
      hidePremium,
    ]
  )

  const handleSelectChange = useCallback(
    (value) => {
      const premium = +getPremium(value)
      const parsedValue = parseInt(value, 10)

      if (!checked) {
        setChecked(true)
        addRemoveAddon({
          actionType: 'add',
          limit: parsedValue,
        })
      }

      onPremiumCalculation({
        ...item,
        limit: parsedValue,
        value: parsedValue,
        premium,
      })
      setSelectedPremium(parsedValue)
      setState((state) => ({
        ...state,
        premium,
      }))
    },
    [getPremium, item, onPremiumCalculation, checked, addRemoveAddon]
  )

  const handleQty = useCallback(
    (qty) => {
      setQty(qty)
      addRemoveAddon({
        limit: selectedPremium || defaultData.defaultSelect,
        actionType: 'add',
        qtyCount: qty,
      })
    },
    [addRemoveAddon, selectedPremium, defaultData.defaultSelect]
  )

  const handleSelectFocus = useCallback(() => {
    if (!checked) {
      setChecked(true)
      addRemoveAddon({
        actionType: 'add',
        limit: selectedPremium || defaultData.defaultSelect,
      })
      if (!hidePremium && item.calc_method === 'p_calc') {
        onPremiumCalculation({
          ...item,
          limit: selectedPremium || defaultData.defaultSelect,
          value: selectedPremium || defaultData.defaultSelect,
        })
      }
    }
  }, [
    checked,
    addRemoveAddon,
    selectedPremium,
    defaultData.defaultSelect,
    hidePremium,
    item,
    onPremiumCalculation,
  ])

  return (
    <AddonItemStyle>
      <Row justify="space-between">
        <div onClick={() => handleChangeCheckbox(item)}>
          <CustomText color={AgentColorPallette.regular} weight={800}>
            {item.add_on_name}
          </CustomText>
          {!hidePremium && (
            <CustomText
              size="10px"
              color={AgentColorPallette.fontSemiGrey}
              top="0"
              weight={700}
            >
              {formatMoney(defaultData.addedPremium, 0, 'Mulai dari  Rp ')}
            </CustomText>
          )}
        </div>
        <CustomCheckbox
          isChecked={checked}
          color={AgentColorPallette.regular}
          onChange={() => handleChangeCheckbox(item)}
          name={`addonCheckbox-${item.add_on_code}`}
          id={`addonCheckbox-${item.add_on_code}`}
        />
      </Row>
      {item.show_drop_down && (
        <Row align="center" className="premium-drop-down-section">
          <div className="drop-down-wrapper">
            <CustomText weight={700} color={AgentColorPallette.darkCharcoal}>
              {LANG_STRINGS.limit}
            </CustomText>
            <Select
              options={data}
              name="Limit"
              value={selectedPremium || defaultData.defaultSelect}
              defaultValue={defaultData.defaultSelect}
              displayKey="display"
              placeholder="Limit"
              className="item-select-wrapper"
              border
              onChange={handleSelectChange}
              onFocus={handleSelectFocus}
            />
          </div>
          {checked && state.isQTYAddon && (
            <QuantityAddRemove
              min={1}
              max={item.max_no_of_passenger || 1}
              onUpdateQty={handleQty}
              quantity={qty}
              className="quantity-add"
            />
          )}
        </Row>
      )}
    </AddonItemStyle>
  )
}

export default AddonItem
