import { useState } from 'react'
import { Button, CustomText } from '../../../../../components'
import BottomActionSheet from '../../../../../components/BottomActionSheet'
import { LANG_STRINGS } from '../../../../../lang/index'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { MultiYearContainer, ButtonContainer, YearButton, CoverageButton, CoverageButtonGroup, CoverageContainer, CoverageLabel, CoverageTitle, SubmitContainer } from './index.style'

function MultiYearBottomSheet ({ show, onClose, onSubmit = () => {}, pageData }) {
  const [selected, setSelected] = useState(pageData?.applicationData?.year_based_package_type_map?.length || null)
  const [coverageSelections, setCoverageSelections] = useState(pageData?.applicationData?.year_based_package_type_map || [])
  const handleYearSelect = (num) => {
    setSelected(num)
    setCoverageSelections(
      Array.from({ length: num }, (_, i) => ({
        year: i + 1,
        package_type: 'car-protection-comprehensive'
      }))
    )
  }

  const handleCoverageSelect = (yearIndex, type) => {
    const newSelections = coverageSelections.map((entry, index) => {
      if (index === yearIndex - 1) {
        return { ...entry, package_type: type }
      } else if (index >= yearIndex && type === 'car-protection-tlo') {
        return { ...entry, package_type: 'car-protection-tlo' }
      }
      return entry
    })
    setCoverageSelections(newSelections)
  }

  return (
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      title='Pilih Perlindungan'
      showHeader
    >
      <MultiYearContainer>
        <CustomText
          color={AgentColorPallette.black}
          size='0.8em'
          bottom='0.5em'
          weight={700}
        >
          Periode Perlindungan
        </CustomText>
        <ButtonContainer>
          {[1, 2, 3, 4, 5].map((num) => (
            <YearButton
              key={num}
              selected={selected === num}
              onClick={() => handleYearSelect(num)}
            >
              {num}
              <br />
              Tahun
            </YearButton>
          ))}
        </ButtonContainer>
        {selected && (
          <CoverageContainer>
            {coverageSelections.map(({ year, package_type }, index) => (
              <div key={year}>
                <CoverageTitle>Perlindungan Tahun ke-{year}</CoverageTitle>
                <CoverageButtonGroup>
                  <CoverageButton
                    selected={package_type === 'car-protection-comprehensive'}
                    disabled={index > 0 && coverageSelections[index - 1].package_type === 'car-protection-tlo'}
                    onClick={() => handleCoverageSelect(year, 'car-protection-comprehensive')}
                  >
                    Komprehensif
                  </CoverageButton>
                  <CoverageButton
                    selected={package_type === 'car-protection-tlo'}
                    onClick={() => handleCoverageSelect(year, 'car-protection-tlo')}
                  >
                    TLO
                  </CoverageButton>
                </CoverageButtonGroup>
                {index > 0 && coverageSelections[index - 1].package_type === 'car-protection-tlo' && (
                  <CoverageLabel>Tidak bisa diubah karena tahun sebelumnya memilih TLO</CoverageLabel>
                )}
              </div>
            ))}
          </CoverageContainer>
        )}
        <SubmitContainer>
          <Button
            onClick={() => onSubmit(coverageSelections)}
            disabled={!selected}
          >
            {LANG_STRINGS.save}
          </Button>
        </SubmitContainer>
      </MultiYearContainer>
    </BottomActionSheet>
  )
}

export default MultiYearBottomSheet
