import { Component } from 'react'
import PropTypes from 'prop-types'
import { PackageItemStyle } from './index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { CustomText } from '../../../../../components'
import { formatMoney } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import { setToLocalStorage } from '../../../../../helpers/localstorage'
import { PACKAGE_CODE, POLICY_PKG_DATA } from '../../../../../constants/cookies'
import { DisplayFlexCCC, DisplayFlexRCC, Grid, Row } from '../../../../../commonStyle/index.style'
import { TIER_A, TIER_B } from '../../../../../images/imageUrl'

class PackageItem extends Component {
  static propTypes = {
    packageItem: PropTypes.object,
    applicationData: PropTypes.object,
    noCardClick: PropTypes.bool,
    purchaseType: PropTypes.string,
    onSaveDraft: PropTypes.func,
    mvOnlinePackageList: PropTypes.bool
  }

  handleCardClick = (packageItem) => {
    // getPayload and map data
    const { applicationData, purchaseType, noCardClick, onSaveDraft } = this.props
    if (noCardClick) return
    const pkgData = {
      applicationData,
      purchaseType,
      package_code: packageItem.code,
      premium: packageItem.premium
    }
    if (applicationData.package_data) {
      delete applicationData.package_data
    }
    setToLocalStorage(PACKAGE_CODE, packageItem.code)
    setToLocalStorage(POLICY_PKG_DATA, pkgData)
    onSaveDraft && onSaveDraft(
      packageItem.code,
      {
        add_ons_cat: packageItem.add_ons,
        premium: packageItem.premium,
        package_code: packageItem?.package?.code,
        provider_code: packageItem?.provider?.code,
        provider_name: packageItem?.provider?.name,
        provider_branch: packageItem?.provider?.headquarter_branch,
        provider_package_code: packageItem.code,
        code: packageItem.code
      },
      true
    )
  }

  renderItemAmount = (text, subText) => {
    return (
      <div>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size='0.5em'
          weight={700}
          className='text-uppercase'
        >
          {text}
        </CustomText>
        <CustomText
          color={AgentColorPallette.blackGrey}
          size='0.75em'
          weight={700}
        >
          {subText}
        </CustomText>
      </div>
    )
  }

  render () {
    const { packageItem, mvOnlinePackageList } = this.props
    return (
      <PackageItemStyle
        onClick={e => this.handleCardClick(packageItem)}
        id={`mobilPkgCardSelect-${packageItem.code}`}
        data-gtm-element-id='MV-packages-list'
        data-package-code={`MV-Card-Select-${packageItem.code}`}
      >
        <Grid className='pkg-details'>
          <DisplayFlexCCC
            className='pkg-name-box'
            data-gtm-element-id='MV-packages-list'
            data-package-code={`MV-Card-Select-${packageItem.code}`}
          >
            {
              ['A', 'B'].includes(packageItem.provider_category) && (
                <div className='pkg-preferred-icon'>
                  <img src={(packageItem.provider_category === 'A') ? TIER_A : TIER_B} alt='Preferred' />
                </div>
              )
            }
            <DisplayFlexRCC
              className='package-img-box'
              data-gtm-element-id='MV-packages-list'
              data-package-code={`MV-${packageItem.code}`}
            >
              <img
                data-gtm-element-id='MV-packages-list'
                data-package-code={`MV-${packageItem.code}`}
                className='package-img'
                src={packageItem.provider.logo_url}
                alt='package-logo'
              />
            </DisplayFlexRCC>
            <div
              data-gtm-element-id='MV-packages-list'
              data-package-code={`MV-${packageItem.code}`}
            >
              <CustomText
                color={AgentColorPallette.blackGrey}
                textAlign='center'
                size='0.9em'
                weight={700}
                data-gtm-element-id='MV-packages-list'
                data-package-code={`MV-${packageItem.code}`}
                top='0.4rem'
              >
                {packageItem.provider.name}
              </CustomText>
              <CustomText
                color={AgentColorPallette.fontDarkerGrey}
                size='0.75em'
                textAlign='center'
                data-gtm-element-id='MV-packages-list'
                data-package-code={`MV-${packageItem.code}`}
              >
                {packageItem.name}
              </CustomText>
            </div>
          </DisplayFlexCCC>
          <div
            className='pkg-item-btm'
            data-gtm-element-id='MV-packages-list'
            data-package-code={`MV-${packageItem.code}`}
          >
            <Row justify='space-between' align='center'>
              {
                this.renderItemAmount(
                  mvOnlinePackageList
                    ? `${LANG_STRINGS.premium} ${packageItem?.premium?.period / 12} ${LANG_STRINGS.year}`
                    : `${LANG_STRINGS.premium} ${packageItem?.premium?.period} ${LANG_STRINGS.months}`,
                  formatMoney(packageItem.premium.amount, 0)
                )
              }
              {
                this.renderItemAmount(
                  LANG_STRINGS.point,
                  Math.floor(packageItem.points)
                )
              }
            </Row>
            <div className='separator' />
            <Row justify='space-between' align='center'>
              <CustomText color={AgentColorPallette.fontDarkerGrey}>
                {LANG_STRINGS.valueOfCoverage}
              </CustomText>
              <CustomText color={AgentColorPallette.fontDarkerGrey}>
                {
                  formatMoney((packageItem.total_sum_insured || (packageItem.vehicle_sum_insured + (packageItem?.accessories_sum_insured || packageItem?.package_data?.accessories_sum_insured || 0))), 0)
                }
              </CustomText>
            </Row>
          </div>
        </Grid>
      </PackageItemStyle>
    )
  }
}

export default PackageItem
