import { updateLoader, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useEffect } from 'react'
import PolicyMVAddonsContainer from './container/MVAddonsContainer'
import PropertyAddonsContainer from './container/PropertyAddonsContainer'
import { PolicyAddonsContextProvider } from './context'

function PolicyAddons (props) {
  const [, dispatchLoader] = useLoaderContextValue()

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_PROVIDER_ADDONS_LOADER: undefined,
        GET_PACKAGE_DETAIL_LOADER: undefined,
        GET_ALL_ADDONS_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  return (
    <PolicyAddonsContextProvider>
      {
        props.isMVProduct ? <PolicyMVAddonsContainer {...props} />
          : <PropertyAddonsContainer {...props} />
      }
    </PolicyAddonsContextProvider>
  )
}

export default PolicyAddons
