import { ConfigUrl } from '../../../../configs/url'

export const PACKAGES_ACTION = {
  GET_PACKAGES_REQUEST: 'GET_PACKAGES_REQUEST',
  GET_PACKAGES: 'GET_PACKAGES',

  GET_PACKAGE_DETAIL_REQUEST: 'GET_PACKAGE_DETAIL_REQUEST',
  GET_PACKAGE_DETAIL: 'GET_PACKAGE_DETAIL',

  SEND_QUOTATION_REQUEST: 'SEND_QUOTATION_REQUEST',
  SEND_QUOTATION: 'SEND_QUOTATION',

  SHARE_DRAFT_QUOTE_REQUEST: 'SHARE_DRAFT_QUOTE_REQUEST',
  SHARE_DRAFT_QUOTE: 'SHARE_DRAFT_QUOTE',

  CREATE_APPLICATION_REQUEST: 'CREATE_APPLICATION_REQUEST',
  CREATE_APPLICATION: 'CREATE_APPLICATION',

  UPDATE_PACKAGE_STORE: 'UPDATE_PACKAGE_STORE',
  SAVE_ADDONS_DATA: 'SAVE_ADDONS_DATA'
}

export const getPackages = (payload) => ({
  type: PACKAGES_ACTION.GET_PACKAGES_REQUEST,
  payload: {
    ...payload,
    url: ConfigUrl.getPackages(payload.body?.code),
    method: 'POST'
  }
})

export const getPackagesDetails = (payload) => ({
  type: PACKAGES_ACTION.GET_PACKAGE_DETAIL_REQUEST,
  payload: {
    ...payload,
    url: ConfigUrl.getPkgDetailV2(payload.packageCode),
    method: 'POST'
  }
})

export const saveAddonsData = (payload) => ({
  type: PACKAGES_ACTION.SAVE_ADDONS_DATA,
  payload: {
    ...payload
  }
})

export const sendQuotationToCustomer = (payload) => ({
  type: PACKAGES_ACTION.SEND_QUOTATION_REQUEST,
  payload: {
    ...payload,
    url: ConfigUrl.sendQuotation,
    method: 'POST'
  }
})

export const shareDraftQuoteToCustomerReq = (payload) => ({
  type: PACKAGES_ACTION.SHARE_DRAFT_QUOTE_REQUEST,
  payload: {
    ...payload,
    url: ConfigUrl.shareDraftQuoteApi,
    method: 'POST'
  }
})

export const createApplication = (payload) => ({
  type: PACKAGES_ACTION.CREATE_APPLICATION_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.createPolicy
  }
})

export const updatePackageStore = (payload) => ({
  type: PACKAGES_ACTION.UPDATE_PACKAGE_STORE,
  payload: {
    ...payload
  }
})
