export const ADDONS_THIRD_PARTY_AMOUNT_RANGE_WITH_MAX = (maxSumInsured, currencyType) => {
  const baseOptions = [
    { value: 5000000 },
    { value: 10000000 },
    { value: 15000000 },
    { value: 20000000 },
    { value: 25000000 },
    { value: 30000000 },
    { value: 35000000 },
    { value: 40000000 },
    { value: 45000000 },
    { value: 50000000 }
  ]

  if (!maxSumInsured) {
    return baseOptions.map(option => ({
      display: formatMoney(getConvertedCurrency(option.value, currencyType?.exchange_rate, 0), 0,
        currencyType?.currency_symbol, currencyType?.currency_symbol === 'Rp' ? ',' : '.',
        currencyType?.currency_symbol === 'Rp' ? '.' : ','),
      value: option.value
    }))
  }

  return baseOptions
    .filter(option => option.value <= maxSumInsured)
    .map(option => ({
      display: formatMoney(getConvertedCurrency(option.value, currencyType?.exchange_rate, 0), 0,
        currencyType?.currency_symbol, currencyType?.currency_symbol === 'Rp' ? ',' : '.',
        currencyType?.currency_symbol === 'Rp' ? '.' : ','),
      value: option.value
    }))
}

