export const getCustomerFormData = (data, isOldQuotation, isRenewalFlow) => {
  let mobile = get(data, 'customer_data.mobile_no', '')
  if (mobile && mobile.includes('62-')) {
    mobile = mobile.substring(3, mobile.length)
  }
  const fields = [
    {
      type: 'upload',
      label: LANG_STRINGS.photoKTP,
      guide: true,
      placeholder: 'Nama Lengkap (sesuai KTP)',
      defaultValue: get(data, 'ktp_url', ''),
      name: 'ktp'
    },
    {
      type: 'ktp',
      label: 'Nomor KTP',
      placeholder: 'Nomor KTP',
      defaultValue: get(data, 'ktp_no', ''),
      name: 'ktp_no',
      className: 'input-field',
      disabled: isRenewalFlow,
      skipEmptyCheck: isOldQuotation
    },
    {
      type: 'name',
      label: 'Nama Lengkap (sesuai KTP)',
      placeholder: 'Nama Lengkap (sesuai KTP)',
      defaultValue: get(data, 'customer_data.name', '') || (isRenewalFlow && get(data, 'name', '')),
      disabled: isRenewalFlow,
      name: 'name'
    }, {
      type: 'phone_number',
      label: 'Nomor Handphone',
      placeholder: 'Nomor Handphone E.g., 08xxxxxxxxx',
      defaultValue: mobile || get(data, 'mobile_no', '').replace(/62-/g, ''),
      className: 'customer-phone-input',
      name: 'mobile_no'
    }, {
      type: 'email',
      label: 'Alamat Email',
      placeholder: 'Alamat Email',
      defaultValue: get(data, 'customer_data.email', '') || (isRenewalFlow && get(data, 'email', '')),
      name: 'email'
    }
  ]

  return {
    fields: fields
  }
}

